function editFinancialProfile(){let p={...S.profile},opts=[{value:'',label:'Selecione uma conta'}].concat(S.banks.map(b=>({value:b.id,label:b.nome+' · '+b.tipo})));openForm('Configurar dados financeiros',[{type:'section',label:'Renda recorrente'},{name:'salarioBase',label:'Salário-base mensal (R$)',type:'number',min:0,step:'.01',required:true},{name:'bonusBase',label:'Bônus recorrente mensal (R$)',type:'number',min:0,step:'.01'},{name:'pagamento',label:'Quando recebe o salário',type:'select',options:['5º dia útil','Último dia útil','Dia fixo do mês']},{name:'contaSalario',label:'Conta em que recebe o salário',type:'select',options:opts},{type:'section',label:'Benefícios com uso restrito'},{name:'homeOffice',label:'Auxílio home office mensal (R$)',type:'number',min:0,step:'.01'},{name:'contaHomeOffice',label:'Conta em que recebe o auxílio home office',type:'select',options:opts},{name:'vrDia',label:'Vale-refeição por dia útil (R$)',type:'number',min:0,step:'.01'},{name:'vaMensal',label:'Vale-alimentação mensal (R$)',type:'number',min:0,step:'.01'}],p,v=>{S.profile={...p,...v,salarioBase:+v.salarioBase||0,bonusBase:+v.bonusBase||0,vrDia:+v.vrDia||0,vaMensal:+v.vaMensal||0,homeOffice:+v.homeOffice||0};S.keys.forEach(k=>{let m=M(k);if(m.salary===undefined||m.salary===0)m.salary=S.profile.salarioBase;if(m.bonus===undefined)m.bonus=S.profile.bonusBase;if(m.homeOffice===undefined||m.homeOffice===0)m.homeOffice=S.profile.homeOffice;if(m.valeAlimentacao===undefined||m.valeAlimentacao===0)m.valeAlimentacao=S.profile.vaMensal});save()})}

function clearAllMonths(){if(!confirm('Zerar os lançamentos de todos os meses? Os meses, bancos, dívidas, metas e assinaturas serão mantidos.'))return;S.keys.forEach(k=>{let old=S.months[k]||{};S.months[k]={salary:0,bonus:0,valeRefeicao:0,valeAlimentacao:0,valeReembolso:0,gastos:[],fixos:[],parcelas:[],reserva:0,rendaFixa:0,esperado:{},aportesMetas:[],nomeMes:old.nomeMes||''}});save();go('painel')}
function exportCSV(){let rows=[['Mês','Tipo','Descrição','Vencimento','Valor','Pago','Forma de pagamento','Categoria']];S.keys.forEach(k=>{let m=S.months[k]||{};[['Gasto',m.gastos],['Conta fixa',m.fixos],['Parcela',m.parcelas]].forEach(([t,ls])=>(ls||[]).forEach(x=>rows.push([k,t,x.nome,x.dia,x.valor,x.pago?'Sim':'Não',x.tipo,x.cat])));[['Salário',m.salary],['Vale-refeição',m.valeRefeicao],['Vale-alimentação',m.valeAlimentacao],['Vale-reembolso',m.valeReembolso]].forEach(([n,v])=>rows.push([k,'Entrada',n,'',v||0,'','','']))});let csv=rows.map(r=>r.map(v=>'"'+String(v??'').replace(/"/g,'""')+'"').join(';')).join('\r\n'),a=document.createElement('a'),u=URL.createObjectURL(new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8'}));a.href=u;a.download='financas.csv';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
function exportPDF(){let w=window.open('','_blank');if(!w){alert('Permita a abertura de janelas para gerar o PDF.');return}let rows=S.keys.map(k=>{let c=calc(k);return '<tr><td>'+esc(full(k))+'</td><td>'+brl(c.entradas)+'</td><td>'+brl(c.gasto)+'</td><td>'+brl(c.saldo)+'</td></tr>'}).join('');w.document.write('<html><meta charset="utf-8"><title>Relatório financeiro</title><style>body{font:12px Arial;padding:25px}table{width:100%;border-collapse:collapse}td,th{padding:8px;border-bottom:1px solid #ddd;text-align:left}</style><h1>Relatório financeiro</h1><table><tr><th>Mês</th><th>Entradas</th><th>Despesas</th><th>Saldo</th></tr>'+rows+'</table><p>Use “Salvar como PDF” na impressão.</p></html>');w.document.close();w.print()}
function annualChart(rows){let mx=Math.max(1,...rows.flatMap(x=>[x.entradas,x.gasto]));return '<section class="panel annual-chart-panel"><h2>Receitas x despesas</h2><div class="annual-bars">'+rows.map(r=>'<div class="annual-bar-col"><div class="annual-bar-pair"><i class="income" style="height:'+(r.entradas/mx*100)+'%"></i><i class="expense" style="height:'+(r.gasto/mx*100)+'%"></i></div><small>'+short(r.k).split('/')[0]+'</small></div>').join('')+'</div><div class="chart-key"><span>● Entradas</span><span>● Gastos</span></div></section>'}

function numInput(k,f,v){return '<input class="inline-number" type="number" min="0" step=".01" value="'+(+v||0)+'" data-change="month" data-month="'+k+'" data-field="'+f+'">'}
function cell(k,key,i,c,r){let[f,label,t]=c,attrs='data-change="row" data-month="'+k+'" data-key="'+key+'" data-index="'+i+'" data-field="'+f+'"';if(t==='b')return '<input type="checkbox" '+(r[f]?'checked':'')+' '+attrs+' aria-label="Pago">';if(t==='n')return '<input class="cell-input numeric" type="number" min="0" step=".01" value="'+(+r[f]||0)+'" '+attrs+'>';if(t==='d')return '<input class="cell-input day" type="number" min="1" max="31" value="'+(+r[f]||1)+'" '+attrs+'>';if(t==='tipo'||t==='cat'){let opts=t==='tipo'?['Débito','Crédito','Pix','Alimentação / Refeição','Auxílio']:S.cats;return '<select class="cell-select" '+attrs+'>'+[...new Set([...opts,r[f]])].map(o=>'<option '+(o===r[f]?'selected':'')+'>'+esc(o)+'</option>').join('')+'</select>'}if(t==='bank')return '<select class="cell-select bank-select" '+attrs+'><option value="">Banco...</option>'+S.banks.map(b=>'<option value="'+esc(b.id)+'" '+(b.id===r[f]?'selected':'')+'>'+esc(b.nome)+'</option>').join('')+'</select>';return '<input class="cell-input" value="'+esc(r[f])+'" '+attrs+' aria-label="'+label+'">'}
function section(k,key,title,desc,extra=''){let all=M(k)[key],cs=cols[key],rows=all.map((r,i)=>({r,i})).filter(({r})=>{let date=k+'-'+String(Math.max(1,Math.min(31,+r.dia||1))).padStart(2,'0');return(!dateFilter.from||date>=dateFilter.from)&&(!dateFilter.to||date<=dateFilter.to)}).sort((a,b)=>key==='fixos'?((a.r.pago?1:0)-(b.r.pago?1:0)||(+a.r.dia||1)-(+b.r.dia||1)):key==='parcelas'?((a.r.pago?1:0)-(b.r.pago?1:0)||(+a.r.dia||1)-(+b.r.dia||1)):0),total=rows.reduce((a,x)=>a+(+x.r.valor||0),0);return '<section class="panel"><div class="panel-head"><div><h2>'+title+'</h2><p>'+desc+'</p></div>'+extra+'</div><div class="table-wrap"><table><thead><tr>'+cs.map(c=>'<th>'+c[1]+'</th>').join('')+'<th></th></tr></thead><tbody>'+rows.map(({r,i})=>'<tr>'+cs.map(c=>'<td>'+cell(k,key,i,c,r)+'</td>').join('')+'<td><button class="icon-button" data-action="delete-row" data-month="'+k+'" data-key="'+key+'" data-index="'+i+'" aria-label="Excluir lançamento">×</button></td></tr>').join('')+'<tr class="total-row"><td colspan="'+(cs.length-1)+'">Total exibido · '+rows.length+' de '+all.length+'</td><td class="num">'+brl(total)+'</td><td></td></tr></tbody></table></div><div class="panel-foot"><span>'+rows.length+' lançamento(s) no filtro</span>'+button('＋ Adicionar','add-row','text','data-month="'+k+'" data-key="'+key+'"')+'</div></section>'}

function donut(by,total){let it=Object.entries(by).filter(x=>x[1]>0).sort((a,b)=>b[1]-a[1]);if(!total)return '<p class="empty">Adicione gastos para ver a distribuição.</p>';let off=0,C=2*Math.PI*43;let arcs=it.map(([c,v])=>{let l=v/total*C,s='<circle r="43" cx="55" cy="55" fill="none" stroke="'+color(c)+'" stroke-width="17" stroke-dasharray="'+l+' '+(C-l)+'" stroke-dashoffset="'+(-off)+'" transform="rotate(-90 55 55)"/>';off+=l;return s}).join('');return '<div class="chart"><svg viewBox="0 0 110 110">'+arcs+'<text x="55" y="52" text-anchor="middle" class="donut-label">GASTOS</text><text x="55" y="66" text-anchor="middle" class="donut-value">'+Math.round(total)+'</text></svg><div class="legend">'+it.map(([c,v])=>'<div><i style="background:'+color(c)+'"></i><span>'+esc(c)+'</span><b>'+((v/total)*100).toFixed(1).replace('.',',')+'%</b></div>').join('')+'</div></div>'}
function monthView(k){let c=calc(k),m=c.m,cats=[...new Set([...S.cats.filter(x=>c.cats[x]||m.esperado[x]),...Object.keys(c.cats)])];return head('PLANEJAMENTO MENSAL',full(k),'Entradas, saídas e escolhas financeiras do mês.',button('← Visão geral','go-panel')+button('Calendário','go-calendario','secondary')+button('＋ Novo mês','new-month','secondary')+button('Duplicar mês','duplicate-month','secondary','data-month="'+k+'"')+button('Renomear','rename-month','text','data-month="'+k+'"')+button('Excluir mês','delete-month','text','data-month="'+k+'"'))+'<div class="metrics">'+metric('Entradas totais',brl(c.entradas),'Inclui salário, extras e benefícios')+metric('Gastos',brl(c.gasto),'Todas as despesas lançadas')+metric('Saldo disponível',brl(c.saldo),'Salário + extras − gastos de caixa − reservas',c.saldo<0?'red':'green')+metric('Benefícios restantes',brl(c.beneficiosRestantes.alimentacao+c.beneficiosRestantes.homeOffice),'Após gastos de alimentação e auxílio')+metric('Reservas',brl(c.inv),'Investimentos e dinheiro guardado')+'</div><div class="grid2"><section class="panel"><div class="panel-head"><div><h2>Entradas</h2><p>Valores previstos</p></div></div><div class="form-row"><label>Salário</label>'+numInput(k,'salary',m.salary)+'</div><div class="form-row"><label>Bônus e extras</label>'+(m.bonusItems||[]).map((x,i)=>'<div class="bonus-row"><div><b>'+esc(x.descricao)+'</b><small>'+(x.data?esc(x.data):'Data não informada')+'</small></div><strong>'+brl(x.valor)+'</strong><button class="icon-action" data-action="edit-bonus" data-month="'+k+'" data-index="'+i+'">✎</button><button class="icon-action danger" data-action="delete-bonus" data-month="'+k+'" data-index="'+i+'">♲</button></div>').join('')+button('＋ Adicionar bônus ou extra','new-bonus','secondary','data-month="'+k+'')+'</div><div class="form-row"><label>Auxílio home office</label>'+numInput(k,'homeOffice',m.homeOffice||0)+'</div><div class="form-row"><label>Vale-refeição</label>'+numInput(k,'valeRefeicao',m.valeRefeicao)+'</div><div class="vr-periods">'+(m.vrPeriodos||[]).map((p,i)=>'<div class="goal-contribution-row"><span>'+esc(p.inicio)+' a '+esc(p.fim)+' · '+(p.dias||'?')+' dias</span><b>'+brl(p.valor)+'</b><button class="button text" data-action="delete-vr-period" data-month="'+k+'" data-index="'+i+'">Excluir</button></div>').join('')+button('＋ Registrar período de vale-refeição','add-vr-period','text','data-month="'+k+'"')+'</div><div class="form-row"><label>Vale-alimentação</label>'+numInput(k,'valeAlimentacao',m.valeAlimentacao)+'</div><div class="form-row"><label>Vale-reembolso</label>'+numInput(k,'valeReembolso',m.valeReembolso)+'</div><div class="sumline"><span>Total de entradas e benefícios</span><b>'+brl(c.entradas)+'</b></div><p class="micro">O saldo disponível não soma vale-refeição, vale-alimentação nem auxílio home office. Gastos pagos com Alimentação / Refeição são abatidos dos vales; gastos pagos como Auxílio são abatidos do home office. Se ultrapassarem o benefício disponível, o excedente reduz o saldo em dinheiro.</p></section><section class="panel"><div class="panel-head"><div><h2>Planos, reservas e investimentos</h2><p>Separe dinheiro, acompanhe metas e registre investimentos</p></div></div><div class="form-row"><label>Reserva</label>'+numInput(k,'reserva',m.reserva)+'</div><div class="form-row"><label>Renda fixa</label>'+numInput(k,'rendaFixa',m.rendaFixa)+'</div><div class="goal-contribution-list">'+(S.goals||[]).map(g=>'<div class="goal-contribution-row"><span>'+esc(g.nome)+'</span><button class="button text" data-action="add-goal-contribution" data-month="'+k+'">＋ Aporte</button><b>'+brl(m.aportesMetas.filter(a=>a.goalId===g.id).reduce((n,a)=>n+(+a.valor||0),0))+'</b></div>').join('')+'</div><div class="investment-list">'+(m.investimentos||[]).map((iv,i)=>'<div class="goal-contribution-row"><span>'+esc(iv.nome)+' · '+esc(iv.tipo)+'</span><b>'+brl(iv.valor)+'</b><button class="button text" data-action="delete-investment" data-month="'+k+'" data-index="'+i+'">Excluir</button></div>').join('')+'</div><div class="subscription-actions">'+button('＋ Adicionar investimento','new-investment','secondary','data-month="'+k+'"')+button('＋ Nova meta','new-goal','text')+'</div><div class="sumline"><span>Total separado</span><b>'+brl(c.inv)+'</b></div></section></div><div class="section-heading"><div><p class="eyebrow">MOVIMENTAÇÕES</p><h2>Organize o mês</h2></div><span>Edite os campos diretamente.</span></div>'+section(k,'gastos','Gastos variáveis','Compras, alimentação, transporte e outras despesas')+'<div class="grid2">'+section(k,'fixos','Contas e despesas fixas','Marque o que já foi pago',button('Copiar mês anterior','copy-prev','text','data-month="'+k+'"'))+section(k,'parcelas','Cartão e parcelas','Compras parceladas e compromissos',button('Gerar próximas parcelas','generate-installments','text','data-month="'+k+'"'))+'</div><section class="panel date-filter-panel"><div class="panel-head"><div><h2>Filtrar despesas por vencimento</h2><p>O filtro afeta as listas e os totais das despesas acima.</p></div><button class="button text" data-action="clear-date-filter">Limpar filtro</button></div><div class="date-filter-fields"><label>De <input type="date" value="'+dateFilter.from+'" data-change="date-filter" data-field="from"></label><label>Até <input type="date" value="'+dateFilter.to+'" data-change="date-filter" data-field="to"></label></div></section>'+bankCreditLimitsView()+'<div class="grid2"><section class="panel"><div class="panel-head"><div><h2>Gastos por categoria</h2><p>Planejado versus realizado</p></div>'+button('＋ Categoria','new-cat','text')+'</div><div class="table-wrap"><table><thead><tr><th>Categoria</th><th>Planejado</th><th>Realizado</th><th>%</th></tr></thead><tbody>'+cats.map(x=>'<tr><td><span class="catname"><i style="background:'+color(x)+'"></i>'+esc(x)+'</span></td><td><input class="cell-input numeric" type="number" min="0" value="'+(m.esperado[x]||'')+'" data-change="expected" data-month="'+k+'" data-category="'+esc(x)+'"></td><td class="num '+(m.esperado[x]&&(c.cats[x]||0)>m.esperado[x]?'text-red':'')+'">'+brl(c.cats[x])+'</td><td class="num">'+(c.gasto?((c.cats[x]||0)/c.gasto*100).toFixed(1):'0.0')+'%</td></tr>').join('')+'</tbody></table></div>'+donut(c.cats,c.gasto)+'</section><section class="panel"><div class="panel-head"><div><h2>Formas de pagamento</h2><p>Distribuição das saídas</p></div></div>'+(Object.entries(c.types).sort((a,b)=>b[1]-a[1]).map(([t,v])=>'<div class="type-row"><span>'+esc(t)+'</span><div><i style="width:'+(c.gasto?v/c.gasto*100:0)+'%"></i></div><b>'+brl(v)+'</b></div>').join('')||'<p class="empty">Nenhum pagamento lançado.</p>')+'</section></div>'}
function panelView(){let rows=S.keys.map(k=>({k,...calc(k)})),sum=f=>rows.reduce((a,r)=>a+f(r),0),debt=S.debts.reduce((a,d)=>a+d.valor,0),paid=S.debts.reduce((a,d)=>a+(Array.isArray(d.historico)?d.historico.reduce((n,p)=>n+(+p.valor||0),0):0),0),initial=S.debts.reduce((a,d)=>a+d.inicial,0),max=Math.max(1,...rows.map(r=>Math.max(r.entradas,r.gasto)));return head('SEU ESPAÇO FINANCEIRO','Olá, '+esc(S.profile?.chamado||'Caio')+'.','Bom ter você por aqui. Vamos deixar seu dinheiro trabalhar a favor dos seus planos.',button('＋ Novo gasto','go-current','primary'))+'<section class="hero"><div><p class="eyebrow light">SEU PRÓXIMO CAPÍTULO COMEÇA AQUI</p><h2>Menos aperto.<br>Mais controle.</h2><p>Um passo de cada vez. Acompanhe seus compromissos, celebre os avanços e transforme seus planos em realidade.</p></div><button type="button" class="hero-stat hero-stat-action" data-action="go-projecao"><span>Saldo projetado no período</span><strong>'+brl(sum(r=>r.saldo))+'</strong><small>Entradas − gastos − reservas · Ver projeção anual ↗</small></button></section>'+(S.goals.some(g=>!g.parentId)?'<section class="panel dashboard-goals"><div class="panel-head"><div><p class="eyebrow">SEUS OBJETIVOS</p><h2>Planos em andamento</h2></div><button class="button secondary" data-action="go-metas">Ver todos</button></div><div class="dashboard-goal-list">'+S.goals.filter(g=>!g.parentId).map(g=>{let target=goalTarget(g),saved=goalSaved(g),pct=target?Math.min(100,saved/target*100):0;return '<button class="dashboard-goal" data-action="goal-detail" data-id="'+g.id+'">'+(g.imagem?'<img src="'+esc(g.imagem)+'" alt="">':'<span class="dashboard-goal-placeholder">✦</span>')+'<span class="dashboard-goal-main"><b>'+esc(g.nome)+'</b><small>'+brl(saved)+' de '+brl(target)+' · faltam '+brl(Math.max(0,target-saved))+'</small><i><em style="width:'+pct+'%"></em></i></span></button>'}).join('')+'</div></section>':'')+'<div class="metrics">'+metric('Entradas previstas',brl(sum(r=>r.entradas)),'Período planejado')+metric('Saldo devedor',brl(debt),'Dívidas em aberto','red')+metric('Pagamentos registrados',brl(paid),'Histórico de quitação','green')+metric('Saldo após despesas',brl(sum(r=>r.saldo)),'Projeção atual',sum(r=>r.saldo)<0?'red':'green')+'</div><div class="grid2"><section class="panel"><div class="panel-head"><div><p class="eyebrow">VISÃO DO PERÍODO</p><h2>Entradas e gastos</h2><p>Selecione uma coluna para abrir o mês.</p></div></div><div class="chart-key"><span>● Entradas</span><span>● Gastos</span></div><div class="bars">'+rows.map(r=>'<button data-action="go-month" data-month="'+r.k+'" title="'+full(r.k)+'"><span class="bar-pair"><i class="income" style="height:'+r.entradas/max*100+'%"></i><i class="expense" style="height:'+r.gasto/max*100+'%"></i></span><small>'+short(r.k).split('/')[0]+'</small></button>').join('')+'</div></section><section class="panel debt-focus"><div class="panel-head"><div><p class="eyebrow">PRIORIDADE</p><h2>Plano para quitar dívidas</h2><p>Registre pagamentos e acompanhe cada saldo.</p></div><span class="pill">'+S.debts.filter(d=>d.valor>0).length+' ativas</span></div><div class="sumline"><span>Saldo devedor</span><b class="text-red">'+brl(debt)+'</b></div><div class="progress"><i style="width:'+(initial?Math.min(100,paid/initial*100):0)+'%"></i></div><div class="progress-meta"><span>'+(initial?Math.round(paid/initial*100):0)+'% quitado*</span><span>'+brl(paid)+' pago</span></div>'+button('Abrir controle de dívidas →','go-debts','primary full')+'<p class="micro">*Considera valores iniciais registrados e pagamentos lançados no aplicativo.</p></section></div><div class="grid2"><section class="panel"><div class="panel-head"><div><h2>Resumo mensal</h2><p>Selecione um mês para abrir os detalhes</p></div></div><div class="table-wrap"><table><thead><tr><th>Mês</th><th>Entradas</th><th>Gastos</th><th>Saldo</th></tr></thead><tbody>'+rows.map(r=>'<tr class="click-row" data-action="go-month" data-month="'+r.k+'"><td>'+full(r.k)+'</td><td class="num">'+brl(r.entradas)+'</td><td class="num">'+brl(r.gasto)+'</td><td class="num '+(r.saldo<0?'text-red':'text-green')+'">'+brl(r.saldo)+'</td></tr>').join('')+'</tbody></table></div></section><section class="panel"><div class="panel-head"><div><h2>Seus dados</h2><p>Backup e portabilidade</p></div></div><p class="body-copy">Tudo fica salvo neste navegador. Exporte um backup antes de limpar os dados ou trocar de aparelho.</p><div class="button-stack">'+button('↓ Exportar backup JSON','export')+button('↓ Exportar CSV','export-csv')+button('↓ Gerar PDF','export-pdf')+button('↑ Importar backup','import')+button('Zerar lançamentos dos meses','clear-all-months','text')+'</div><p class="micro">A sincronização entre dispositivos ficará para uma próxima etapa.</p></section></div>'+bankMovementSummary(S.keys.includes(today)?today.slice(0,7):S.keys[S.keys.length-1]||'')+'<section class="panel moto-card"><div class="panel-head"><div><p class="eyebrow">CONTROLE PESSOAL</p><h2>Minha moto</h2><p>Gasolina, manutenção e reserva.</p></div><span class="moto-icon">🏍</span></div><div class="moto-stats"><div><small>Gastos com a moto</small><b>'+brl(rows.reduce((n,r)=>n+r.m.gastos.concat(r.m.fixos,r.m.parcelas).filter(x=>/^Moto\\s*·/i.test(x.cat||'')).reduce((z,x)=>z+(+x.valor||0),0),0))+'</b></div><div><small>Reserva para a moto</small><b>'+brl(rows.reduce((n,r)=>n+(+r.m.motoReserva||0),0))+'</b></div></div>'+button('Ver controle da moto','go-moto','secondary')+'</section>'}
function debtView(){let total=S.debts.reduce((a,d)=>a+d.valor,0),initial=S.debts.reduce((a,d)=>a+d.inicial,0),paid=S.debts.reduce((a,d)=>a+d.historico.reduce((n,p)=>n+(+p.valor||0),0),0),done=S.debts.filter(d=>d.valor<=0).length,arr=S.debts.filter(d=>filter==='todas'||(filter==='ativas'?d.valor>0:d.valor<=0)).sort((a,b)=>b.valor-a.valor),groups=[['Cartão de crédito',S.debts.filter(d=>d.tipoDivida==='Cartão de crédito')],['Empréstimos',S.debts.filter(d=>['Empréstimo','Empréstimo pessoal'].includes(d.tipoDivida))],['Empréstimos de terceiros',S.debts.filter(d=>d.tipoDivida==='Empréstimo de terceiros')]],mx=Math.max(1,...groups.map(g=>g[1].reduce((n,d)=>n+d.valor,0)));return head('PLANO DE QUITAÇÃO','Dívidas, sem perder o controle.','Acompanhe saldos, compare tipos e veja seu progresso.',button('＋ Nova dívida','new-debt','primary'))+'<div class="metrics">'+metric('Saldo devedor',brl(total),'O que falta pagar','red')+metric('Valor inicial',brl(initial),'Referência do progresso')+metric('Total pago',brl(paid),'Pagamentos registrados','green')+metric('Dívidas quitadas',done+' de '+S.debts.length,'Compromissos concluídos')+'</div><section class="panel debt-breakdown"><h2>Composição das dívidas</h2><p>Saldo em aberto por tipo.</p>'+groups.map(([name,list])=>{let v=list.reduce((n,d)=>n+d.valor,0);return '<div class="debt-type-row"><div><span>'+esc(name)+'</span><b>'+brl(v)+'</b><small>'+list.filter(d=>d.valor>0).length+' em aberto</small></div><div class="debt-type-track"><i style="width:'+(v/mx*100)+'%"></i></div></div>'}).join('')+'</section><section class="panel"><h2>Seu caminho até quitar</h2><div class="progress large"><i style="width:'+(initial?Math.min(100,paid/initial*100):0)+'%"></i></div><div class="progress-meta"><span>'+(initial?Math.round(paid/initial*100):0)+'% quitado</span><b>'+brl(total)+' restante</b></div><div class="filter-row"><span>Mostrar</span><div class="filters">'+[['todas','Todas'],['ativas','Em aberto'],['quitadas','Quitadas']].map(([v,t])=>'<button class="'+(filter===v?'selected':'')+'" data-action="filter" data-filter="'+v+'">'+t+'</button>').join('')+'</div></div></section><div class="debts">'+arr.map(d=>{let i=S.debts.indexOf(d),progress=d.inicial?Math.max(0,Math.min(100,(d.inicial-d.valor)/d.inicial*100)):0,bank=S.banks.find(x=>x.id===d.bancoId);return '<article class="debt-card"><div class="debt-top"><div><span class="debt-index">DÍVIDA '+String(i+1).padStart(2,'0')+'</span><h2>'+esc(d.nome)+'</h2><p>'+esc(d.tipoDivida||'Dívida')+(bank?' · '+esc(bank.nome):'')+' · '+(d.vencimento?'Vencimento dia '+esc(d.vencimento):'Vencimento não informado')+'</p></div>'+button('Ver detalhes','detail-debt','secondary','data-index="'+i+'"')+button('Editar','edit-debt','text','data-index="'+i+'"')+'</div><div class="debt-amounts"><div><span>Saldo atual</span><strong class="'+(d.valor>0?'text-red':'text-green')+'">'+brl(d.valor)+'</strong></div><div><span>Valor inicial</span><strong>'+brl(d.inicial)+'</strong></div></div><div class="progress"><i style="width:'+progress+'%"></i></div><div class="progress-meta"><span>'+Math.round(progress)+'% quitado</span><span>'+brl(Math.max(0,d.inicial-d.valor))+' amortizado</span></div>'+(d.observacao?'<p class="debt-note">'+esc(d.observacao)+'</p>':'')+'<div class="debt-actions">'+(d.valor>0?button('＋ Registrar pagamento','pay-debt','primary','data-index="'+i+'"'):'<span class="paid">✓ Dívida quitada</span>')+button('Histórico ('+d.historico.length+')','history','secondary','data-index="'+i+'"')+'</div></article>'}).join('')+'</div><p class="micro">As dívidas estão ordenadas do maior saldo para o menor.</p>'}
function debtFields(){let opts=[{value:'',label:'Não vinculada'}].concat(S.banks.map(b=>({value:b.id,label:b.nome+' · '+b.tipo})));return [{name:'nome',label:'Nome da dívida',required:true},{name:'tipoDivida',label:'Tipo de dívida',type:'select',required:true,options:['Cartão de crédito','Cartão de débito','Empréstimo','Empréstimo pessoal','Empréstimo de terceiros']},{name:'bancoId',label:'Banco ou instituição',type:'select',options:opts},{name:'valor',label:'Saldo devedor atual (R$)',type:'number',min:0,step:'.01',required:true},{name:'inicial',label:'Valor total original (R$)',type:'number',min:0,step:'.01'},{name:'parcelada',label:'É parcelada?',type:'select',options:[{value:'0',label:'Não'},{value:'1',label:'Sim'}]},{name:'valorParcela',label:'Valor de cada parcela (R$)',type:'number',min:0,step:'.01'},{name:'totalParcelas',label:'Quantidade total de parcelas',type:'number',min:0,step:1},{name:'dataInicio',label:'Data da primeira parcela',type:'date'},{name:'dia',label:'Dia de vencimento',type:'number',min:1,max:31,step:1},{name:'observacao',label:'Observações',type:'textarea'}]}
function debtCategory(t){return t==='Cartão de crédito'?'Cartão de crédito':t==='Cartão de débito'?'Cartão de débito':t==='Empréstimo de terceiros'?'Empréstimo de terceiros':t==='Empréstimo pessoal'?'Empréstimo pessoal':'Dívida de empréstimo'}
function newDebt(){openForm('Nova dívida',debtFields(),{valor:0,inicial:0,parcelada:'0',valorParcela:0,totalParcelas:0,dataInicio:today+'-01',dia:10,tipoDivida:'Empréstimo',bancoId:''},v=>{let d={id:'d'+Date.now(),...v,cat:debtCategory(v.tipoDivida),valor:+v.valor||0,inicial:+v.inicial||+v.valor||0,parcelada:v.parcelada==='1',valorParcela:+v.valorParcela||0,totalParcelas:+v.totalParcelas||0,dia:+v.dia||10,historico:[],vencimento:String(+v.dia||10)};S.debts.push(d);if(d.parcelada&&d.totalParcelas&&d.valorParcela)generateDebtInstallments(d);save()})}
function editDebt(i){let d=S.debts[i];openForm('Editar dívida',debtFields(),{parcelada:d.parcelada?'1':'0',...d},v=>{Object.assign(d,v,{cat:debtCategory(v.tipoDivida),valor:+v.valor||0,inicial:+v.inicial||+v.valor||0,parcelada:v.parcelada==='1',valorParcela:+v.valorParcela||0,totalParcelas:+v.totalParcelas||0,dia:+v.dia||10});d.vencimento=String(d.dia);if(d.parcelada&&d.totalParcelas&&d.valorParcela)generateDebtInstallments(d);save()})}
function debtDetail(i){let d=S.debts[i];if(!d)return;let bank=S.banks.find(x=>x.id===d.bancoId),dlg=document.getElementById('debt-detail-dialog');if(dlg)dlg.remove();dlg=document.createElement('dialog');dlg.id='debt-detail-dialog';dlg.className='finance-dialog';let history=(d.historico||[]).slice().sort((a,b)=>String(b.data).localeCompare(String(a.data)));dlg.innerHTML='<div class="debt-detail-content"><div class="dialog-head"><h2>'+esc(d.nome)+'</h2><button type="button" class="button secondary" data-detail-close>×</button></div><p class="eyebrow">'+esc(d.tipoDivida||'Dívida')+'</p><div class="debt-detail-grid"><div><small>Saldo devedor</small><strong>'+brl(d.valor)+'</strong></div><div><small>Valor original</small><strong>'+brl(d.inicial)+'</strong></div><div><small>Instituição</small><strong>'+esc(bank?.nome||'Não vinculada')+'</strong></div><div><small>Vencimento</small><strong>'+esc(d.vencimento?'Dia '+d.vencimento:'Não informado')+'</strong></div><div><small>Parcelamento</small><strong>'+esc(d.parcelada?d.totalParcelas+' parcelas de '+brl(d.valorParcela):'Não parcelada')+'</strong></div><div><small>Categoria</small><strong>'+esc(d.cat||debtCategory(d.tipoDivida))+'</strong></div></div>'+(d.observacao?'<p class="debt-note">'+esc(d.observacao)+'</p>':'')+'<h3>Histórico de pagamentos</h3>'+(history.map(p=>'<div class="calendar-event"><div><b>'+brl(p.valor)+'</b><small>'+esc(p.data||'Data não informada')+(p.nota?' · '+esc(p.nota):'')+'</small></div></div>').join('')||'<p class="micro">Nenhum pagamento registrado.</p>')+'<div class="dialog-actions"><button type="button" class="button secondary" data-detail-close>Fechar</button><button type="button" class="button secondary" data-detail-edit>Editar dívida</button>'+(d.valor>0?'<button type="button" class="button primary" data-detail-pay>Registrar pagamento</button>':'')+'</div></div>';document.body.appendChild(dlg);dlg.querySelectorAll('[data-detail-close]').forEach(b=>b.onclick=()=>dlg.close());dlg.querySelector('[data-detail-edit]').onclick=()=>{dlg.close();editDebt(i)};let pay=dlg.querySelector('[data-detail-pay]');if(pay)pay.onclick=()=>{dlg.close();payDebt(i)};dlg.addEventListener('close',()=>dlg.remove(),{once:true});dlg.showModal()}

function goalChildren(id){return S.goals.filter(g=>g.parentId===id)}
function goalOwnTarget(g){return (g.itens||[]).reduce((n,x)=>n+(+x.valor||0),0)||(+g.alvo||0)}
function goalTarget(g){return goalOwnTarget(g)+goalChildren(g.id).reduce((n,c)=>n+goalTarget(c),0)}
function goalSaved(g){let own=S.keys.reduce((n,k)=>n+M(k).aportesMetas.filter(a=>a.goalId===g.id).reduce((z,a)=>z+(+a.valor||0),0),0);return own+goalChildren(g.id).reduce((n,c)=>n+goalSaved(c),0)}
function goalCard(g){let target=goalTarget(g),saved=goalSaved(g),pct=target?Math.min(100,saved/target*100):0,children=goalChildren(g.id);return '<article class="panel goal-card '+(g.tipo==='Plano'?'goal-plan':'goal-meta')+'">'+(g.imagem?'<img class="goal-cover" src="'+esc(g.imagem)+'" alt="'+esc(g.nome)+'" loading="lazy" onerror="this.style.display=\'none\'">':'<div class="goal-cover goal-cover-placeholder"><span>'+(g.tipo==='Plano'?'✦':'◎')+'</span></div>')+'<div class="goal-card-content"><p class="eyebrow">'+esc(g.tipo||'Meta')+(g.parentId?' · SUBOBJETIVO':'')+'</p><h2>'+esc(g.nome)+'</h2><p>'+esc(g.descricao||'')+'</p><strong>'+brl(saved)+' / '+brl(target)+'</strong><div class="progress"><i style="width:'+pct+'%"></i></div><div class="progress-meta"><span>'+Math.round(pct)+'% concluído</span><b>Faltam '+brl(Math.max(0,target-saved))+'</b></div><p class="micro">'+(g.prazo?'Prazo: '+esc(g.prazo):'Sem prazo definido')+(children.length?' · '+children.length+' item(ns) dentro':'')+'</p><div class="goal-card-actions">'+button('Ver detalhes','goal-detail','secondary','data-id="'+g.id+'"')+button('＋ Adicionar dentro','new-child-goal','primary','data-id="'+g.id+'"')+'</div></div></article>'}
function goalsView(){let roots=S.goals.filter(g=>!g.parentId);return head('PLANOS E METAS','Objetivos claros, passos possíveis.','Planos de longo prazo podem conter metas, etapas e despesas detalhadas.',button('＋ Novo objetivo','new-goal','primary'))+'<div class="goal-create-options"><button class="button secondary" data-action="new-goal" data-goal-type="Meta">＋ Adicionar uma meta</button><button class="button primary" data-action="new-goal" data-goal-type="Plano">＋ Adicionar um plano</button></div>'+(roots.length?'<div class="goal-grid">'+roots.map(goalCard).join('')+'</div>':'<section class="panel goal-empty"><div class="goal-empty-icon">✦</div><h2>Seus planos começam aqui</h2><p>Crie uma viagem, uma compra importante ou uma meta de curto prazo. Você pode adicionar imagem, orçamento, etapas e metas dentro de um plano.</p><button class="button primary" data-action="new-goal" data-goal-type="Plano">Criar meu primeiro plano</button></section>')+'<div class="goal-subsection"><h2>Metas independentes</h2><p>Objetivos de curto prazo que não pertencem a outro plano.</p><div class="goal-grid">'+(S.goals.filter(g=>!g.parentId&&g.tipo==='Meta').map(goalCard).join('')||'<p class="micro">Nenhuma meta independente cadastrada.</p>')+'</div></div>'}
function goalFields(parentId=''){let parentOpts=[{value:'',label:'Nenhum — objetivo principal'}].concat(S.goals.filter(g=>g.tipo==='Plano').map(g=>({value:g.id,label:g.nome})));return [{name:'tipo',label:'O que você quer criar?',type:'select',options:['Plano','Meta'],required:true},{name:'parentId',label:'Dentro de qual plano?',type:'select',options:parentOpts},{name:'nome',label:'Nome do plano ou meta',required:true},{name:'alvo',label:'Valor total (R$)',type:'number',min:0,step:'.01',required:true},{name:'prazo',label:'Prazo previsto',type:'month'},{name:'imagem',label:'URL direta da imagem (opcional)'},{name:'descricao',label:'Descrição e o que está incluído',type:'textarea'}]}
function newGoal(parentId='',forcedType=''){let defaults={tipo:forcedType||'Meta',parentId,nome:'',alvo:0,prazo:'',imagem:'',descricao:''};openForm(parentId?'Adicionar objetivo dentro do plano':'Adicionar plano ou meta',goalFields(parentId),defaults,v=>{let g={id:'g'+Date.now(),tipo:v.tipo||'Meta',parentId:v.parentId||parentId||'',nome:v.nome,alvo:+v.alvo||0,prazo:v.prazo||'',imagem:v.imagem||'',descricao:v.descricao||'',itens:[]};if(g.tipo==='Plano')g.parentId='';S.goals.push(g);save()})}
function editGoal(id){let g=S.goals.find(x=>x.id===id);if(!g)return;openForm('Editar '+(g.tipo||'meta').toLowerCase(),goalFields(id),{tipo:'Meta',parentId:'',...g},v=>{Object.assign(g,v,{alvo:+v.alvo||0,parentId:v.tipo==='Plano'?'':(v.parentId||''),imagem:v.imagem||''});save()})}
function addGoalItem(id){let g=S.goals.find(x=>x.id===id);if(!g)return;openForm('Adicionar item à meta',[{name:'nome',label:'Item (voo, hospedagem, alimentação...)',required:true},{name:'valor',label:'Valor estimado (R$)',type:'number',min:0,step:'.01',required:true},{name:'bancoId',label:'Onde está o dinheiro?',type:'select',options:[{value:'',label:'Ainda não vinculado'}].concat(S.banks.map(b=>({value:b.id,label:b.nome})) )},{name:'rende',label:'O dinheiro rende?',type:'select',options:[{value:'0',label:'Não rende / ainda não sei'},{value:'1',label:'Sim, rende'}]},{name:'observacao',label:'Observações'}],{valor:0,rende:'0'},v=>{g.itens=g.itens||[];g.itens.push({id:'gi'+Date.now(),nome:v.nome,valor:+v.valor||0,bancoId:v.bancoId||'',rende:v.rende==='1',observacao:v.observacao});g.alvo=g.itens.reduce((n,x)=>n+(+x.valor||0),0);save()})}
function goalDetail(id){let g=S.goals.find(x=>x.id===id);if(!g)return;let dlg=document.createElement('dialog');dlg.className='finance-dialog goal-detail-dialog';function draw(){let children=goalChildren(g.id),target=goalTarget(g),saved=goalSaved(g);dlg.innerHTML='<div class="dialog-head"><div><p class="eyebrow">'+esc(g.tipo||'Meta')+'</p><h2>'+esc(g.nome)+'</h2></div><button class="button secondary" data-close>×</button></div>'+(g.imagem?'<img class="goal-detail-cover" src="'+esc(g.imagem)+'" alt="'+esc(g.nome)+'" onerror="this.style.display=\'none\'">':'')+'<p>'+esc(g.descricao||'')+'</p><div class="goal-detail-total"><span>Valor total deste objetivo e dos itens internos</span><strong>'+brl(target)+'</strong><small>Acumulado: '+brl(saved)+' · Faltam '+brl(Math.max(0,target-saved))+'</small></div><h3>Etapas e despesas</h3><div class="goal-item-list">'+(g.itens||[]).map((x,i)=>'<div class="goal-item-row"><div><b>'+esc(x.nome)+'</b><small>'+esc(x.observacao||'')+(x.bancoId?' · '+esc(S.banks.find(b=>b.id===x.bancoId)?.nome||'Banco'):'')+(x.rende?' · Rende juros':' · Sem rendimento')+'</small></div><strong>'+brl(x.valor)+'</strong><button class="icon-action" data-edit-item="'+i+'">✎</button><button class="icon-action danger" data-delete-item="'+i+'">♲</button></div>').join('')+'</div><h3>Objetivos dentro deste '+(g.tipo||'objetivo').toLowerCase()+'</h3><div class="goal-child-list">'+(children.map(c=>'<div class="goal-child-row">'+(c.imagem?'<img src="'+esc(c.imagem)+'" alt="" onerror="this.style.display=\'none\'">':'<span class="goal-child-icon">◎</span>')+'<div><b>'+esc(c.nome)+'</b><small>'+esc(c.tipo||'Meta')+' · '+brl(goalTarget(c))+'</small></div><button class="button secondary" data-open-child="'+esc(c.id)+'">Abrir</button><button class="icon-action" data-edit-child="'+esc(c.id)+'">✎</button></div>').join('')||'<p class="micro">Ainda não há metas ou etapas internas.</p>')+'</div><div class="dialog-actions"><button class="button secondary" data-close>Fechar</button><button class="button secondary" data-edit-goal>Editar</button><button class="button secondary" data-add-item>＋ Despesa/etapa</button><button class="button primary" data-add-child>＋ Meta dentro</button></div>';dlg.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>dlg.close());dlg.querySelector('[data-edit-goal]').onclick=()=>{dlg.close();editGoal(id)};dlg.querySelector('[data-add-item]').onclick=()=>{dlg.close();addGoalItem(id)};dlg.querySelector('[data-add-child]').onclick=()=>{dlg.close();newGoal(id,'Meta')};dlg.querySelectorAll('[data-open-child]').forEach(b=>b.onclick=()=>{dlg.close();goalDetail(b.dataset.openChild)});dlg.querySelectorAll('[data-edit-child]').forEach(b=>b.onclick=()=>{dlg.close();editGoal(b.dataset.editChild)});dlg.querySelectorAll('[data-delete-item]').forEach(b=>b.onclick=()=>{if(confirm('Excluir esta etapa?')){g.itens.splice(+b.dataset.deleteItem,1);g.alvo=g.itens.reduce((n,x)=>n+(+x.valor||0),0);save();draw()}});dlg.querySelectorAll('[data-edit-item]').forEach(b=>b.onclick=()=>{let x=g.itens[+b.dataset.editItem],opts=[{value:'',label:'Ainda não vinculado'}].concat(S.banks.map(b=>({value:b.id,label:b.nome})));dlg.close();openForm('Editar etapa ou despesa',[{name:'nome',label:'Nome da etapa',required:true},{name:'valor',label:'Valor (R$)',type:'number',min:0,step:'.01',required:true},{name:'bancoId',label:'Onde está o dinheiro?',type:'select',options:opts},{name:'rende',label:'O dinheiro rende?',type:'select',options:[{value:'0',label:'Não rende / ainda não sei'},{value:'1',label:'Sim, rende'}]},{name:'observacao',label:'Observações'}],{rende:'0',...x},v=>{Object.assign(x,v,{valor:+v.valor||0,rende:v.rende==='1'});g.alvo=g.itens.reduce((n,z)=>n+(+z.valor||0),0);save();goalDetail(id)})});}document.body.appendChild(dlg);dlg.addEventListener('close',()=>{dlg.remove();render()},{once:true});draw();dlg.showModal()}
function newInvestment(k=cur){openForm('Adicionar investimento',[{name:'nome',label:'Nome do investimento',required:true},{name:'tipo',label:'Tipo (CDB, renda fixa, cofrinho...)',required:true},{name:'valor',label:'Valor separado (R$)',type:'number',min:0,step:'.01',required:true},{name:'instituicao',label:'Banco ou plataforma'},{name:'observacao',label:'Observações',type:'textarea'}],{tipo:'CDB',valor:0},v=>{let m=M(k);m.investimentos.push({...v,valor:+v.valor||0,data:new Date().toISOString().slice(0,10)});save()})}
function addVrPeriod(k=cur){openForm('Registrar crédito de vale-refeição',[{name:'inicio',label:'Período: de',type:'date',required:true},{name:'fim',label:'Período: até',type:'date',required:true},{name:'valor',label:'Valor recebido (R$)',type:'number',min:0,step:'.01',required:true},{name:'dias',label:'Quantidade de dias cobertos',type:'number',min:1,step:1},{name:'observacao',label:'Observações',type:'textarea'}],{inicio:k+'-01',fim:k+'-30',dias:7,valor:(+S.profile?.vrDia||36.4)*7},v=>{if(v.fim<v.inicio){alert('A data final precisa ser igual ou posterior à inicial.');return false}let m=M(k);m.vrPeriodos.push({id:'vr'+Date.now(),...v,valor:+v.valor||0,dias:+v.dias||0});m.valeRefeicao=Math.round(m.vrPeriodos.reduce((n,p)=>n+(+p.valor||0),0)*100)/100;save()})}
function deleteVrPeriod(k,i){let m=M(k);if(!confirm('Excluir este período de vale-refeição?'))return;m.vrPeriodos.splice(i,1);m.valeRefeicao=Math.round(m.vrPeriodos.reduce((n,p)=>n+(+p.valor||0),0)*100)/100;save();render()}
function newGoal(){let nome=(prompt('Nome da meta:')||'').trim();if(!nome)return;let v=prompt('Valor desejado (R$):','');if(v===null)return;let alvo=+v.replace(',','.');if(!Number.isFinite(alvo)||alvo<=0)return alert('Informe um valor válido.');let prazo=prompt('Prazo opcional (AAAA-MM):','');if(prazo===null)return;let descricao=prompt('Descrição opcional:','')||'';S.goals.push({id:'g'+Date.now(),nome,alvo,prazo,descricao});save();render()}
function addGoalContribution(k){if(!S.goals.length)return alert('Cadastre uma meta primeiro.');if(!S.months[k]){k=(prompt('Em qual mês registrar o aporte? (AAAA-MM)',S.keys[0]||today)||'').trim();if(!/^[0-9]{4}-(0[1-9]|1[0-2])$/.test(k))return alert('Informe o mês no formato AAAA-MM.');if(!S.months[k]){S.months[k]={salary:0,bonus:0,gastos:[],fixos:[],parcelas:[],reserva:0,rendaFixa:0,esperado:{},aportesMetas:[]};S.keys.push(k);S.keys.sort()}}let n=prompt('Número da meta:\n'+S.goals.map((g,i)=>(i+1)+'. '+g.nome).join('\n'),'1');if(n===null)return;let g=S.goals[+n-1];if(!g)return alert('Meta inválida.');let v=prompt('Valor do aporte (R$):','');if(v===null)return;let valor=+v.replace(',','.');if(!Number.isFinite(valor)||valor<=0)return alert('Valor inválido.');M(k).aportesMetas.push({id:'a'+Date.now(),goalId:g.id,valor,dia:1});save();render()}
function banksView(){return head('BANCOS E CONTAS','Onde seu dinheiro está.','Gerencie instituições, cartões, limites e a movimentação de cada conta.',button('＋ Adicionar instituição','new-bank','primary'))+'<div class="goal-grid">'+S.banks.map(b=>'<article class="panel bank-card" style="--bank-color:'+esc(b.cor||bankColor(b.nome))+'"><div class="bank-card-top"><span class="bank-logo" style="background:'+esc(b.cor||bankColor(b.nome))+'">'+esc(b.nome.slice(0,1).toUpperCase())+'</span><div class="bank-card-actions"><button class="icon-action" data-action="edit-bank" data-id="'+esc(b.id)+'" title="Editar instituição">✎</button><button class="icon-action danger" data-action="delete-bank" data-id="'+esc(b.id)+'" title="Excluir instituição">♲</button></div></div><p class="eyebrow">'+esc(b.tipo)+'</p><h2>'+esc(b.nome)+'</h2><p>'+esc(b.identificador||'Identificação não informada')+'</p><div class="bank-product-tags">'+(b.cartaoDebito?'<span>Débito</span>':'')+(b.cartaoCredito?'<span>Crédito</span>':'')+(b.temEmprestimo?'<span>Empréstimo</span>':'')+(b.limiteOrigem==='Viracrédito / CDB'?'<span>Viracrédito / CDB</span>':'')+'</div><div class="bank-limits">'+(b.cartaoCredito?'<span>Limite liberado <b>'+brl(b.limiteCartao)+'</b></span><span>Limite mensal <b>'+brl(b.limiteMensal)+'</b></span>':'')+(b.temEmprestimo?'<span>Limite de empréstimo <b>'+brl(b.limiteEmprestimo)+'</b></span>':'')+'</div><p class="micro">'+esc(b.nota||'')+'</p><label class="bank-color-field">Cor da instituição <input type="color" value="'+esc(b.cor||bankColor(b.nome))+'" data-change="bank-color" data-id="'+esc(b.id)+'"></label>'+(S.profile?.contaSalario===b.id?'<span class="pill">Recebe salário</span>':'')+(S.profile?.contaHomeOffice===b.id?'<span class="pill">Recebe auxílio home office</span>':'')+'</article>').join('')+'</div>'}
function bankFields(){return [{type:'section',label:'Identificação'},{name:'nome',label:'Nome da instituição',required:true},{name:'tipo',label:'Tipo de instituição',type:'select',required:true,options:['Banco','Carteira digital','Corretora','Financeira','Cooperativa de crédito','Instituição de pagamento','Outro']},{name:'identificador',label:'Identificação da conta ou cartão (opcional)'},{name:'nota',label:'Observações (opcional)',type:'textarea'},{name:'cor',label:'Cor da instituição',type:'color'},{type:'section',label:'Produtos e serviços'},{name:'cartaoDebito',label:'Possui cartão de débito?',type:'select',options:[{value:'0',label:'Não'},{value:'1',label:'Sim'}]},{name:'cartaoCredito',label:'Possui cartão de crédito?',type:'select',options:[{value:'0',label:'Não'},{value:'1',label:'Sim'}]},{name:'limiteCartao',label:'Limite de crédito liberado (R$)',type:'number',min:0,step:'.01',showIf:{field:'cartaoCredito',value:'1'}},{name:'limiteMensal',label:'Limite disponível para usar no mês (R$)',type:'number',min:0,step:'.01',showIf:{field:'cartaoCredito',value:'1'}},{name:'limiteOrigem',label:'Origem do limite de crédito',type:'select',options:['Instituição','Viracrédito / CDB'],showIf:{field:'cartaoCredito',value:'1'}},{name:'temEmprestimo',label:'Possui linha de empréstimo?',type:'select',options:[{value:'0',label:'Não'},{value:'1',label:'Sim'}]},{name:'limiteEmprestimo',label:'Limite de empréstimo liberado (R$)',type:'number',min:0,step:'.01',showIf:{field:'temEmprestimo',value:'1'}}]}
function bankValues(b={}){return {tipo:'Banco',identificador:'',nota:'',cor:bankColor(b.nome||''),cartaoDebito:'0',cartaoCredito:'0',temEmprestimo:'0',limiteCartao:0,limiteMensal:0,limiteOrigem:'Instituição',limiteEmprestimo:0,...b,cartaoDebito:b.cartaoDebito?'1':'0',cartaoCredito:b.cartaoCredito?'1':'0',temEmprestimo:b.temEmprestimo?'1':'0'}}
function saveBankValues(v,b){return {...b,...v,cartaoDebito:v.cartaoDebito==='1',cartaoCredito:v.cartaoCredito==='1',temEmprestimo:v.temEmprestimo==='1',limiteCartao:+v.limiteCartao||0,limiteMensal:+v.limiteMensal||0,limiteEmprestimo:+v.limiteEmprestimo||0,cor:v.cor||bankColor(v.nome)}}
function newBank(){openForm('Adicionar instituição',bankFields(),bankValues(),v=>{S.banks.push(saveBankValues(v,{id:'b'+Date.now()}));save()})}
function editBank(id){let b=S.banks.find(x=>x.id===id);if(!b)return;openForm('Editar instituição',bankFields(),bankValues(b),v=>{Object.assign(b,saveBankValues(v,b));save()})}
function motoView(){let rows=S.keys.map(k=>({k,m:M(k)})),items=rows.flatMap(r=>[...(r.m.gastos||[]),...(r.m.fixos||[]),...(r.m.parcelas||[])].filter(x=>/^Moto\s*·/i.test(x.cat||'')).map(x=>({...x,mes:r.k}))),total=items.reduce((n,x)=>n+(+x.valor||0),0),reserve=rows.reduce((n,r)=>n+(+r.m.motoReserva||0),0),by={};items.forEach(x=>by[x.cat]=(by[x.cat]||0)+(+x.valor||0));return head('MINHA MOTO','Acompanhe os custos da sua moto.','Registre gasolina, manutenção e reserve dinheiro para os próximos cuidados.',button('＋ Registrar gasto','moto-add-expense','primary'))+'<div class="metrics">'+metric('Gastos registrados',brl(total),'Todos os meses')+metric('Reserva para a moto',brl(reserve),'Dinheiro separado')+metric('Lançamentos',items.length,'Custos identificados')+'</div><div class="grid2"><section class="panel"><h2>Gastos por categoria</h2>'+(Object.entries(by).sort((a,b)=>b[1]-a[1]).map(([k,v])=>'<div class="bank-movement-row"><span class="bank-dot" style="background:#ffe608"></span><div class="bank-movement-name"><b>'+esc(k.replace(/^Moto\s*·\s*/,''))+'</b></div><strong>'+brl(v)+'</strong></div>').join('')||'<p class="empty">Ainda não há gastos com a moto.</p>')+'</section><section class="panel"><h2>Reserva para a moto</h2><p>Informe quanto deseja separar no planejamento mensal.</p><div class="form-row"><label>Reserva deste mês (R$)</label>'+numInput(S.keys.includes(today)?today.slice(0,7):S.keys[S.keys.length-1],'motoReserva',M(S.keys.includes(today)?today.slice(0,7):S.keys[S.keys.length-1]).motoReserva||0)+'</div><p class="micro">A reserva é dinheiro separado, não um gasto de consumo.</p></section></div><section class="panel"><h2>Histórico de gastos</h2>'+(items.length?'<div class="table-wrap"><table><thead><tr><th>Mês</th><th>Descrição</th><th>Categoria</th><th>Banco</th><th>Valor</th></tr></thead><tbody>'+items.map(x=>'<tr><td>'+full(x.mes)+'</td><td>'+esc(x.nome)+'</td><td>'+esc(x.cat)+'</td><td>'+esc(S.banks.find(b=>b.id===x.bancoId)?.nome||'—')+'</td><td class="num">'+brl(x.valor)+'</td></tr>').join('')+'</tbody></table></div>':'<p class="empty">Seus gastos de moto aparecerão aqui.</p>')+'</section>'}
function addMotoExpense(){let k=S.keys.includes(today)?today.slice(0,7):S.keys[S.keys.length-1];if(!k)return;cur=k;let m=M(k);m.gastos.push({nome:'',dia:new Date().getDate(),tipo:'Débito',cat:'Moto · Gasolina',bancoId:'',valor:0});save();render()}
function entriesView(){let rows=(S.movements||[]).slice().sort((a,b)=>String(b.data).localeCompare(String(a.data))),total=rows.reduce((n,x)=>n+(+x.valor||0),0);return head('ENTRADAS','Registre o dinheiro que chega.','Acompanhe cada entrada por data, origem e instituição.',button('＋ Registrar entrada','new-entry','primary'))+'<div class="metrics">'+metric('Total registrado',brl(total),'Entradas cadastradas')+metric('Lançamentos',rows.length,'Movimentações registradas')+'</div><section class="panel"><div class="panel-head"><div><h2>Histórico de entradas</h2><p>Selecione o banco para acompanhar a movimentação por instituição.</p></div></div>'+(rows.length?'<div class="table-wrap"><table><thead><tr><th>Data</th><th>Descrição</th><th>Banco</th><th>Tipo</th><th>Valor</th><th></th></tr></thead><tbody>'+rows.map(x=>'<tr><td>'+esc(x.data||'')+'</td><td>'+esc(x.nome)+'</td><td>'+esc(S.banks.find(b=>b.id===x.bancoId)?.nome||'Não informado')+'</td><td>'+esc(x.tipo||'Entrada')+'</td><td class="num">'+brl(x.valor)+'</td><td><button class="icon-button" data-action="edit-entry" data-id="'+esc(x.id)+'">✎</button><button class="icon-button" data-action="delete-entry" data-id="'+esc(x.id)+'">×</button></td></tr>').join('')+'</tbody></table></div>':'<p class="empty">Ainda não há entradas registradas. Use “Registrar entrada” para começar.</p>')+'</section>'}
function entryFields(){return [{name:'nome',label:'Descrição da entrada',required:true},{name:'valor',label:'Valor recebido (R$)',type:'number',min:0.01,step:'.01',required:true},{name:'data',label:'Data do recebimento',type:'date',required:true},{name:'bancoId',label:'Conta em que recebeu',type:'select',required:true,options:[{value:'',label:'Selecione uma conta'},...S.banks.map(b=>({value:b.id,label:b.nome}))]},{name:'tipo',label:'Origem',type:'select',options:['Salário','Bônus','Vale-refeição','Vale-alimentação','Auxílio home office','Reembolso','Transferência','Rendimento de investimento','Outra entrada']},{name:'observacao',label:'Observações'}]}
function newBonus(k){let m=M(k);openForm('Adicionar bônus ou extra',[{name:'descricao',label:'Descrição do bônus ou extra',required:true},{name:'valor',label:'Valor (R$)',type:'number',min:0,step:'.01',required:true},{name:'data',label:'Data do recebimento',type:'date'},{name:'observacao',label:'Observações'}],{valor:0,data:new Date().toISOString().slice(0,10)},v=>{m.bonusItems=m.bonusItems||[];m.bonusItems.push({id:'bx'+Date.now(),descricao:v.descricao,valor:+v.valor||0,data:v.data,observacao:v.observacao});save()})}
function editBonus(k,i){let m=M(k),x=(m.bonusItems||[])[i];if(!x)return;openForm('Editar bônus ou extra',[{name:'descricao',label:'Descrição',required:true},{name:'valor',label:'Valor (R$)',type:'number',min:0,step:'.01',required:true},{name:'data',label:'Data do recebimento',type:'date'},{name:'observacao',label:'Observações'}],x,v=>{Object.assign(x,v,{valor:+v.valor||0});save()})}
function deleteBonus(k,i){let m=M(k);if(!m.bonusItems?.[i]||!confirm('Excluir este bônus ou extra?'))return;m.bonusItems.splice(i,1);save();render()}
function newEntry(){openForm('Registrar entrada',entryFields(),{valor:0,data:new Date().toISOString().slice(0,10),bancoId:S.profile?.contaSalario||'',tipo:'Outra entrada'},v=>{S.movements.push({id:'mv'+Date.now(),...v,valor:+v.valor||0});save()})}
function editEntry(id){let x=S.movements.find(y=>y.id===id);if(!x)return;openForm('Editar entrada',entryFields(),x,v=>{Object.assign(x,v,{valor:+v.valor||0});save()})}
function bankCreditLimitsView(){let list=S.banks.filter(b=>b.cartaoCredito);return '<section class="panel bank-credit-limits"><div class="panel-head"><div><h2>Limites de crédito do mês</h2><p>Limite informado por instituição. Viracrédito/CDB fica identificado como dinheiro vinculado a investimento.</p></div></div>'+(list.length?list.map(b=>'<div class="bank-movement-row"><span class="bank-dot" style="background:'+esc(b.cor||bankColor(b.nome))+'"></span><div class="bank-movement-name"><b>'+esc(b.nome)+(b.limiteOrigem==='Viracrédito / CDB'?' · Viracrédito / CDB':'')+'</b><small>Limite liberado '+brl(b.limiteCartao)+' · Limite mensal '+brl(b.limiteMensal)+'</small></div><strong>'+brl(b.limiteMensal||b.limiteCartao)+'</strong></div>').join(''):'<p class="empty">Cadastre um cartão de crédito em Bancos e contas para ver seus limites aqui.</p>')+'</section>'}
function bankMovementSummary(k){let m=M(k),items=[...(m.gastos||[]),...(m.fixos||[]),...(m.parcelas||[])],by=S.banks.map(b=>{let incoming=(S.movements||[]).filter(x=>x.bancoId===b.id&&String(x.data||'').slice(0,7)===k).reduce((n,x)=>n+(+x.valor||0),0),outgoing=items.filter(x=>x.bancoId===b.id).reduce((n,x)=>n+(+x.valor||0),0);return{b,incoming,outgoing,net:incoming-outgoing}}).filter(x=>x.incoming||x.outgoing);return '<section class="panel"><div class="panel-head"><div><h2>Movimentações por banco</h2><p>Entradas registradas e despesas associadas a cada conta.</p></div><button class="button text" data-action="go-entradas">＋ Entradas</button></div>'+(by.length?by.map(x=>'<div class="bank-movement-row"><span class="bank-dot" style="background:'+esc(x.b.cor||bankColor(x.b.nome))+'"></span><div class="bank-movement-name"><b>'+esc(x.b.nome)+'</b><small>Entradas '+brl(x.incoming)+' · Saídas '+brl(x.outgoing)+'</small></div><strong class="'+(x.net<0?'text-red':'text-green')+'">'+brl(x.net)+'</strong></div>').join(''):'<p class="empty">Associe despesas aos bancos e registre entradas para ver a movimentação por conta.</p>')+'</section>'}
function subscriptionsView(){return head('ASSINATURAS','Configure uma vez. Planeje todo mês.','Edite ou exclua uma recorrência. O mês inicial define quando ela começa a aparecer.',button('＋ Nova assinatura','new-subscription','primary'))+'<section class="panel subscriptions-panel"><div class="table-wrap"><table><thead><tr><th>Descrição</th><th>Dia</th><th>Valor</th><th>Pagamento</th><th>Categoria</th><th>Começa em</th><th>Ações</th></tr></thead><tbody>'+(S.subscriptions.map((sub,i)=>'<tr><td>'+esc(sub.nome)+'</td><td>'+(sub.regraVencimento==='5º dia útil'?'5º dia útil':sub.dia)+'</td><td>'+brl(sub.valor)+'</td><td>'+esc(sub.tipo)+'</td><td>'+esc(sub.cat)+'</td><td>'+esc(sub.inicio||'Imediato')+'</td><td><div class="subscription-row-actions"><button type="button" class="icon-action" data-action="edit-subscription" data-index="'+i+'" title="Editar assinatura" aria-label="Editar '+esc(sub.nome)+'">✎</button><button type="button" class="icon-action danger" data-action="delete-subscription" data-index="'+i+'" title="Excluir assinatura" aria-label="Excluir '+esc(sub.nome)+'">♲</button></div></td></tr>').join('')||'<tr><td colspan="7">Cadastre uma despesa recorrente.</td></tr>')+'</tbody></table></div><div class="subscription-actions">'+button('＋ Nova assinatura','new-subscription','secondary')+button('Aplicar ao mês atual e ao próximo','apply-subscriptions','primary')+'</div></section>'}
function newSubscription(){let start=S.keys.includes(cur)?cur:today;openForm('Nova assinatura',[{name:'nome',label:'Nome da despesa recorrente',required:true},{name:'valor',label:'Valor (R$)',type:'number',min:0,step:'.01',required:true},{name:'regraVencimento',label:'Quando vence?',type:'select',options:[{value:'dia-fixo',label:'Dia fixo do mês'},{value:'5º dia útil',label:'5º dia útil do mês'}]},{name:'dia',label:'Dia da cobrança (se fixo)',type:'number',min:1,max:31,step:1,required:true,showIf:{field:'regraVencimento',value:'dia-fixo'}},{name:'tipo',label:'Forma de pagamento',type:'select',options:['Débito','Crédito','Pix','Alimentação / Refeição','Auxílio']},{name:'cat',label:'Categoria'},{name:'inicio',label:'Começa em qual mês?',type:'month',required:true},{name:'observacao',label:'Observações',type:'textarea'}],{valor:0,dia:5,regraVencimento:'dia-fixo',tipo:'Débito',cat:'Assinaturas',inicio:start},v=>{let sub={id:'s'+Date.now(),nome:v.nome,valor:+v.valor||0,dia:+v.dia||5,regraVencimento:v.regraVencimento||'dia-fixo',tipo:v.tipo||'Débito',cat:v.cat||'Assinaturas',observacao:v.observacao,ativo:true,inicio:v.inicio};S.subscriptions.push(sub);let [y,mo]=v.inicio.split('-').map(Number);[0,1].forEach(offset=>{let dt=new Date(y,mo-1+offset,1),k=dt.getFullYear()+'-'+String(dt.getMonth()+1).padStart(2,'0'),m=M(k);if(!m.fixos.some(x=>x.subscriptionId===sub.id))m.fixos.push({nome:sub.nome,dia:subscriptionDueDay(dt.getFullYear(),dt.getMonth(),sub),tipo:sub.tipo,cat:sub.cat,valor:sub.valor,pago:false,subscriptionId:sub.id,regraVencimento:sub.regraVencimento})});save()})}
function editSubscription(i){let sub=S.subscriptions[i];if(!sub)return;openForm('Editar assinatura',[{name:'nome',label:'Descrição',required:true},{name:'valor',label:'Valor (R$)',type:'number',min:0,step:'.01',required:true},{name:'regraVencimento',label:'Quando vence?',type:'select',options:[{value:'dia-fixo',label:'Dia fixo do mês'},{value:'5º dia útil',label:'5º dia útil do mês'}]},{name:'dia',label:'Dia da cobrança (se fixo)',type:'number',min:1,max:31,step:1,required:true,showIf:{field:'regraVencimento',value:'dia-fixo'}},{name:'tipo',label:'Forma de pagamento',type:'select',options:['Débito','Crédito','Pix','Alimentação / Refeição','Auxílio']},{name:'cat',label:'Categoria'},{name:'inicio',label:'Começa a cobrar em qual mês?',type:'month',required:true},{name:'observacao',label:'Observações',type:'textarea'}],{regraVencimento:'dia-fixo',...sub},v=>{let oldId=sub.id;Object.assign(sub,v,{valor:+v.valor||0,dia:Math.min(31,Math.max(1,+v.dia||5)),regraVencimento:v.regraVencimento||'dia-fixo',ativo:true});S.keys.forEach(k=>{let m=S.months[k];if(!m)return;m.fixos=(m.fixos||[]).filter(r=>r.subscriptionId!==oldId||r.pago);});let [y,mo]=sub.inicio.split('-').map(Number);[0,1].forEach(offset=>{let dt=new Date(y,mo-1+offset,1),k=dt.getFullYear()+'-'+String(dt.getMonth()+1).padStart(2,'0'),m=M(k);if(!m.fixos.some(x=>x.subscriptionId===sub.id))m.fixos.push({nome:sub.nome,dia:subscriptionDueDay(dt.getFullYear(),dt.getMonth(),sub),tipo:sub.tipo||'Débito',cat:sub.cat||'Assinaturas',valor:sub.valor,pago:false,subscriptionId:sub.id,regraVencimento:sub.regraVencimento})});save()})}
function deleteSubscription(i){let sub=S.subscriptions[i];if(!sub||!confirm('Excluir a assinatura “'+sub.nome+'”? Os lançamentos futuros ainda não pagos vinculados a ela também serão removidos.'))return;S.subscriptions.splice(i,1);S.keys.forEach(k=>{let m=S.months[k];if(m)m.fixos=(m.fixos||[]).filter(r=>r.subscriptionId!==sub.id||r.pago)});save();render()}
function applySubscriptions(){let base=S.keys.includes(cur)?cur:today,[y,mo]=base.split('-').map(Number),months=[base,(()=>{let d=new Date(y,mo,1);return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')})()],added=0;months.forEach(k=>{let m=M(k);S.subscriptions.filter(sub=>sub.ativo!==false&&(!sub.inicio||k>=sub.inicio)).forEach(sub=>{if(!m.fixos.some(x=>x.subscriptionId===sub.id||x.nome===sub.nome)){m.fixos.push({nome:sub.nome,dia:subscriptionDueDay(+k.slice(0,4),+k.slice(5,7)-1,sub),tipo:sub.tipo,cat:sub.cat,valor:sub.valor,pago:false,subscriptionId:sub.id,regraVencimento:sub.regraVencimento||'dia-fixo'});added++}})});save();render();alert(added+' conta(s) recorrente(s) adicionada(s) aos meses selecionados.')}
function annualView(){let y=projectionYear,rows=Array.from({length:12},(_,i)=>{let k=y+'-'+String(i+1).padStart(2,'0'),m=S.months[k],c=m?calc(k):null;return{k,exists:!!m,entradas:c?c.entradas:0,gasto:c?c.gasto:0,reservas:c?c.inv:0,saldo:c?c.saldo:0}}),cum=0;rows.forEach(r=>{cum+=r.saldo;r.acumulado=cum});let total=f=>rows.reduce((n,r)=>n+r[f],0);return head('PROJEÇÃO ANUAL','Veja o ano antes de vivê-lo.','Entradas totais incluem benefícios; o saldo disponível considera salário e extras, desconta gastos pagos em dinheiro, excedentes dos benefícios e reservas.',button('← Visão geral','go-panel'))+'<section class="panel"><div class="panel-head"><div><h2>Planejamento de '+y+'</h2><p>Saldo mensal e acumulado são indicadores diferentes.</p></div><select data-change="projection-year">'+[y-1,y,y+1,...S.keys.map(k=>+k.slice(0,4))].filter((v,i,a)=>a.indexOf(v)===i).sort((a,b)=>a-b).map(v=>'<option value="'+v+'" '+(v===y?'selected':'')+'>'+v+'</option>').join('')+'</select></div><div class="metrics">'+metric('Entradas anuais',brl(total('entradas')),'Inclui benefícios')+metric('Gastos anuais',brl(total('gasto')),'Despesas lançadas')+metric('Reservas e metas',brl(total('reservas')),'Dinheiro separado')+metric('Saldo disponível anual',brl(total('saldo')),'Após despesas de caixa e reservas',total('saldo')<0?'red':'green')+'</div>'+annualChart(rows)+'<div class="table-wrap"><table><thead><tr><th>Mês</th><th>Status</th><th>Entradas</th><th>Gastos</th><th>Reservas/metas</th><th>Saldo disponível</th><th>Acumulado</th><th></th></tr></thead><tbody>'+rows.map(r=>'<tr><td>'+new Date(y,+r.k.slice(5)-1,1).toLocaleDateString('pt-BR',{month:'long'})+'</td><td>'+(r.exists?'Planejado':'Sem dados')+'</td><td>'+brl(r.entradas)+'</td><td>'+brl(r.gasto)+'</td><td>'+brl(r.reservas)+'</td><td class="'+(r.saldo<0?'text-red':'text-green')+'">'+brl(r.saldo)+'</td><td class="'+(r.acumulado<0?'text-red':'text-green')+'">'+brl(r.acumulado)+'</td><td>'+button(r.exists?'Abrir':'Planejar','go-month','text','data-month="'+r.k+'"')+'</td></tr>').join('')+'</tbody></table></div><p class="micro">Meses vazios contam como zero. O acumulado não inclui saldo bancário inicial. Benefícios não são tratados como dinheiro livre para pagar dívidas.</p></section>'}

function fifthBusinessDay(year,month){let d=new Date(year,month,1),n=0;while(d.getMonth()===month){let day=d.getDay();if(day!==0&&day!==6)n++;if(n===5)return d;d.setDate(d.getDate()+1)}return d}
function subscriptionDueDate(year,month,sub){if(sub.regraVencimento==='5º dia útil')return fifthBusinessDay(year,month);let days=new Date(year,month+1,0).getDate(),day=Math.min(days,Math.max(1,+sub.dia||1)),d=new Date(year,month,day);while(d.getDay()===0||d.getDay()===6)d.setDate(d.getDate()+1);return d}
function subscriptionDueDay(year,month,sub){return subscriptionDueDate(year,month,sub).getDate()}
function showCalendarDay(date,events){let old=document.getElementById('calendar-day-dialog');if(old)old.remove();let d=document.createElement('dialog');d.id='calendar-day-dialog';d.className='finance-dialog';d.innerHTML='<form method="dialog"><div class="dialog-head"><h2>'+esc(new Date(date+'T12:00:00').toLocaleDateString('pt-BR',{weekday:'long',day:'numeric',month:'long',year:'numeric'}))+'</h2><button type="submit">×</button></div><div class="calendar-day-details">'+(events.length?events.map(e=>'<div class="calendar-event"><div><b>'+esc(e.nome)+'</b><small>'+esc(e.tipo||'Compromisso financeiro')+(e.pago?' · Pago':'')+'</small></div><strong>'+brl(e.valor)+'</strong></div>').join(''):'<p>Não há compromissos cadastrados para este dia.</p>')+'</div><div class="dialog-actions"><button type="submit" class="button primary">Fechar</button></div></form>';document.body.appendChild(d);d.addEventListener('close',()=>d.remove(),{once:true});d.showModal()}
function easterSunday(year){let a=year%19,b=Math.floor(year/100),c=year%100,d=Math.floor(b/4),e=b%4,f=Math.floor((b+8)/25),g=Math.floor((b-f+1)/3),h=(19*a+b-d-g+15)%30,i=Math.floor(c/4),j=c%4,l=(32+2*e+2*i-h-j)%7,n=Math.floor((a+11*h+22*l)/451),month=Math.floor((h+l-7*n+114)/31),day=(h+l-7*n+114)%31+1;return new Date(year,month-1,day)}
function brazilHoliday(date){let y=date.getFullYear(),md=(date.getMonth()+1)+'-'+date.getDate(),fixed=['1-1','4-21','5-1','9-7','10-12','11-2','11-15','11-20','12-25'];if(fixed.includes(md))return true;let easter=easterSunday(y),days=[-2,60].map(n=>{let d=new Date(easter);d.setDate(d.getDate()+n);return d});return days.some(d=>d.toDateString()===date.toDateString())}
function businessDay(date){return date.getDay()!==0&&date.getDay()!==6&&!brazilHoliday(date)}
function salaryBenefitEvents(year,month,day,m){let out=[],date=new Date(year,month,day),fifth=fifthBusinessDay(year,month).getDate();if(day===fifth){out.push({nome:'Recebimento do salário (5º dia útil)',valor:+(m.salary??S.profile?.salarioBase)||0,pago:false,tipo:'Entrada prevista'});out.push({nome:'Vale-alimentação mensal',valor:+(m.valeAlimentacao??S.profile?.vaMensal)||0,pago:false,tipo:'Benefício previsto'})}
let monday=new Date(date);monday.setDate(date.getDate()-((date.getDay()+6)%7));let credit=new Date(monday);while(!businessDay(credit)&&credit.getDay()!==0&&credit.getDay()!==6)credit.setDate(credit.getDate()+1);if(date.toDateString()===credit.toDateString()){let workdays=0;for(let n=0;n<5;n++){let d=new Date(monday);d.setDate(monday.getDate()+n);if(d.getMonth()===month&&businessDay(d))workdays++}out.push({nome:'Crédito semanal de vale-refeição',valor:Math.round((+S.profile?.vrDia||36.4)*workdays*100)/100,pago:false,tipo:'Benefício previsto ('+workdays+' dias úteis)'})}return out}
function calendarView(){let d=calendarDate,y=d.getFullYear(),mo=d.getMonth(),first=new Date(y,mo,1),days=new Date(y,mo+1,0).getDate(),offset=(first.getDay()+6)%7,k=y+'-'+String(mo+1).padStart(2,'0'),m=S.months[k]||{gastos:[],fixos:[],parcelas:[]},events={};[...(m.gastos||[]).map(r=>({...r,tipo:'Gasto'})),...(m.fixos||[]).map(r=>({...r,tipo:'Conta fixa'})),...(m.parcelas||[]).map(r=>({...r,tipo:'Parcela'}))].forEach(r=>{let day=Math.min(days,Math.max(1,+r.dia||1));(events[day]||(events[day]=[])).push({nome:r.nome,valor:+r.valor||0,pago:!!r.pago,tipo:r.tipo})});(S.subscriptions||[]).filter(x=>x.ativo!==false&&(!x.inicio||k>=x.inicio)).forEach(x=>{let due=subscriptionDueDate(y,mo,x),day=due.getMonth()===mo?due.getDate():Math.min(days,Math.max(1,+x.dia||1));(events[day]||(events[day]=[]));if(!events[day].some(e=>e.nome===x.nome))events[day].push({nome:x.nome,valor:+x.valor||0,pago:false,tipo:x.regraVencimento==='5º dia útil'?'Assinatura · 5º dia útil':'Assinatura prevista'})});for(let day=1;day<=days;day++){let income=salaryBenefitEvents(y,mo,day,m);if(income.length)(events[day]||(events[day]=[])).push(...income)}let cells=Array.from({length:offset},()=>'<div class="calendar-day blank"></div>');for(let day=1;day<=days;day++){let ev=events[day]||[],now=day===new Date().getDate()&&mo===new Date().getMonth()&&y===new Date().getFullYear();cells.push('<button type="button" data-action="calendar-day" data-date="'+y+'-'+String(mo+1).padStart(2,'0')+'-'+String(day).padStart(2,'0')+'" class="calendar-day '+(now?'is-today':'')+' '+(ev.length?'has-events':'')+'"><b>'+day+'</b>'+ev.slice(0,2).map(x=>'<small class="'+(x.pago?'is-paid':'')+'">'+esc(x.nome)+'</small>').join('')+(ev.length>2?'<small>+'+(ev.length-2)+' mais</small>':'')+'</button>')}return head('CALENDÁRIO FINANCEIRO','Seus compromissos, dia a dia.','Contas, parcelas, salário e benefícios previstos.',button('← Visão geral','go-panel'))+'<section class="panel"><div class="calendar-toolbar">'+button('← Anterior','calendar-prev','secondary')+'<h2>'+first.toLocaleDateString('pt-BR',{month:'long',year:'numeric'})+'</h2>'+button('Próximo →','calendar-next','secondary')+'</div><div class="calendar-grid">'+['Seg','Ter','Qua','Qui','Sex','Sáb','Dom'].map(x=>'<div class="calendar-weekday">'+x+'</div>').join('')+cells.join('')+'</div><p class="micro">Salário e vale-alimentação: 5º dia útil. Vale-refeição: primeiro dia útil de cada semana, com previsão calculada pelos dias úteis daquela semana. Feriados nacionais são considerados.</p></section>'}
function clearAllMonths(){if(!confirm('Zerar os lançamentos de todos os meses? Os meses, bancos, dívidas, metas e assinaturas serão mantidos.'))return;S.keys.forEach(k=>{let m=S.months[k]||{};S.months[k]={salary:0,bonus:0,valeRefeicao:0,valeAlimentacao:0,valeReembolso:0,gastos:[],fixos:[],parcelas:[],reserva:0,rendaFixa:0,investimentos:[],vrPeriodos:[],esperado:{},aportesMetas:[],nomeMes:m.nomeMes||''}});save();go('painel')}
